reference.catalog.go:
package fixture
type Catalog struct { Items []string }
func (c Catalog) All() []string {return c.Items}
func (c Catalog) Page(offset,limit int)([]string,int){if offset<0||offset>=len(c.Items)||limit<=0{return []string{},-1};end:=len(c.Items);if limit<len(c.Items)-offset{end=offset+limit};next:=-1;if end<len(c.Items){next=end};return c.Items[offset:end],next}

